-- A sheet's pending SLA in days, not dated (null: none): a PENDING claim whose pending day plus it is
-- before the sheet's today is late pending.
ALTER TABLE sheet ADD COLUMN pending_sla INT;
-- The sheet's today when the claim last went to PENDING (null: it never did).
ALTER TABLE claim ADD COLUMN pending_on DATE;
ALTER TABLE claim_history ADD COLUMN pending_on DATE;
-- The sheet's today when the share was added (null: before shares were dated, held always): a sheet
-- read as of a date shows only the shares added on or before it.
ALTER TABLE claim_share ADD COLUMN on_date DATE;
-- The order a sheet's periods were added in: a larger one added later.
ALTER TABLE period ADD COLUMN added_seq BIGINT AUTO_INCREMENT;
-- Whether a steward set the claim's due-by directly: a holiday added later does not move it.
ALTER TABLE claim ADD COLUMN due_by_set BOOLEAN DEFAULT FALSE NOT NULL;
-- A person's aliases: trimmed, each unique on the sheet (ignoring case) among all names and aliases.
CREATE TABLE person_alias (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet(id),
    person_id BIGINT NOT NULL REFERENCES person(id),
    alias VARCHAR(200) NOT NULL
);
CREATE INDEX person_alias_sheet ON person_alias(sheet_id);
